-- Reconcile eight exact Purina Pro Plan retailer identities to eight
-- already verified manufacturer-current formulas.
--
-- Retailer sitemap titles and reviewed package fronts are identity evidence
-- only. This migration does not update product_data, ingredients, images,
-- formula versions, scoring, or verification tiers. Five Chewy rows have an
-- independently reviewed exact package-front match. Three Walmart rows have
-- complete protected title identities but no retailer image and remain
-- explicitly title-identity-only.

CREATE TEMP TABLE purina_pro_plan_retailer_alias_payload
ON COMMIT DROP
AS
SELECT
  raw.*,
  public.normalize_verified_product_search_query(raw.retailer_title)
    AS normalized_alias
FROM jsonb_to_recordset(
  convert_from(
    decode('', 'base64'),
    'utf8'
  )::JSONB
) AS raw(
  alias_formula_key TEXT,
  retailer_title TEXT,
  retailer_source_url TEXT,
  retailer_product_id TEXT,
  retailer_front_image_url TEXT,
  retailer_front_image_sha256 TEXT,
  retailer_observed_at TIMESTAMPTZ,
  retailer_source_slug TEXT,
  manual_package_image_match BOOLEAN,
  review_method TEXT,
  review_reason TEXT,
  target_cache_key TEXT,
  expected_catalog_formula_key TEXT,
  target_brand TEXT,
  target_product_name TEXT,
  target_product_line TEXT,
  target_flavor TEXT,
  target_pet_type TEXT,
  target_life_stage TEXT,
  target_food_form TEXT,
  target_source_url TEXT,
  target_gtin TEXT,
  target_package_size TEXT,
  target_artifact_image_url TEXT,
  target_artifact_image_sha256 TEXT,
  target_database_image_url TEXT,
  target_ingredient_count INTEGER,
  target_database_ingredient_hash TEXT,
  target_canonical_ingredient_hash TEXT,
  target_raw_ingredient_hash TEXT,
  target_verified_at TIMESTAMPTZ,
  identity_signature JSONB,
  formula_id_hint BIGINT
);

DO $payload_guard$
DECLARE
  v_key TEXT;
BEGIN
  IF (SELECT count(*) FROM purina_pro_plan_retailer_alias_payload) <> 8 THEN
    RAISE EXCEPTION 'Purina Pro Plan retailer identity payload must contain 8 rows';
  END IF;

  IF (
    SELECT count(DISTINCT alias_formula_key)
    FROM purina_pro_plan_retailer_alias_payload
  ) <> 8 OR (
    SELECT count(DISTINCT retailer_source_url)
    FROM purina_pro_plan_retailer_alias_payload
  ) <> 8 OR (
    SELECT count(DISTINCT normalized_alias)
    FROM purina_pro_plan_retailer_alias_payload
  ) <> 8 OR (
    SELECT count(DISTINCT target_cache_key)
    FROM purina_pro_plan_retailer_alias_payload
  ) <> 8 OR (
    SELECT count(DISTINCT formula_id_hint)
    FROM purina_pro_plan_retailer_alias_payload
  ) <> 8 THEN
    RAISE EXCEPTION 'Purina Pro Plan retailer identity keys are not unique';
  END IF;

  SELECT alias_formula_key
  INTO v_key
  FROM purina_pro_plan_retailer_alias_payload
  WHERE NULLIF(btrim(alias_formula_key), '') IS NULL
     OR NULLIF(btrim(retailer_title), '') IS NULL
     OR NULLIF(btrim(retailer_source_url), '') IS NULL
     OR NULLIF(btrim(retailer_product_id), '') IS NULL
     OR NULLIF(btrim(review_reason), '') IS NULL
     OR NULLIF(btrim(target_cache_key), '') IS NULL
     OR NULLIF(btrim(expected_catalog_formula_key), '') IS NULL
     OR NULLIF(btrim(target_product_name), '') IS NULL
     OR NULLIF(btrim(target_product_line), '') IS NULL
     OR NULLIF(btrim(target_source_url), '') IS NULL
     OR NULLIF(btrim(target_gtin), '') IS NULL
     OR NULLIF(btrim(target_package_size), '') IS NULL
     OR NULLIF(btrim(target_artifact_image_url), '') IS NULL
     OR NULLIF(btrim(target_database_image_url), '') IS NULL
     OR target_artifact_image_sha256 !~ '^[a-f0-9]{64}$'
     OR target_database_ingredient_hash !~ '^[a-f0-9]{64}$'
     OR target_canonical_ingredient_hash !~ '^[a-f0-9]{64}$'
     OR target_raw_ingredient_hash !~ '^[a-f0-9]{64}$'
     OR target_ingredient_count < 5
     OR target_verified_at IS NULL
     OR normalized_alias IS NULL
     OR length(normalized_alias) < 2
     OR review_method <> 'exact_purina_pro_plan_retailer_identity_only'
  LIMIT 1;

  IF FOUND THEN
    RAISE EXCEPTION 'Purina Pro Plan retailer identity payload is incomplete: %', v_key;
  END IF;

  IF (
    SELECT count(*)
    FROM purina_pro_plan_retailer_alias_payload
    WHERE retailer_source_slug = 'chewy-public-sitemap'
      AND manual_package_image_match
      AND retailer_front_image_url LIKE 'https://image.chewy.com/%'
      AND retailer_front_image_sha256 ~ '^[a-f0-9]{64}$'
  ) <> 5 OR (
    SELECT count(*)
    FROM purina_pro_plan_retailer_alias_payload
    WHERE retailer_source_slug = 'walmart-public-sitemap'
      AND NOT manual_package_image_match
      AND coalesce(retailer_front_image_url, '') = ''
      AND coalesce(retailer_front_image_sha256, '') = ''
  ) <> 3 THEN
    RAISE EXCEPTION 'Purina Pro Plan retailer image/source partition changed';
  END IF;

  SELECT alias_formula_key
  INTO v_key
  FROM purina_pro_plan_retailer_alias_payload
  WHERE lower(btrim(target_brand)) <> 'purina pro plan'
     OR target_pet_type NOT IN ('dog', 'cat')
     OR target_life_stage NOT IN ('adult', 'puppy')
     OR target_food_form NOT IN ('dry', 'wet')
     OR target_source_url NOT LIKE 'https://www.purina.com/%'
     OR target_artifact_image_url NOT LIKE 'https://www.purina.com/%'
     OR target_database_image_url NOT LIKE 'https://www.purina.com/%'
     OR target_gtin !~ '^[0-9]{12,14}$'
     OR identity_signature ->> 'brand' <> 'purina pro plan'
     OR identity_signature ->> 'pet_type' <> target_pet_type
     OR identity_signature ->> 'life_stage' <> target_life_stage
     OR identity_signature ->> 'food_form' <> target_food_form
     OR NULLIF(identity_signature ->> 'breed_size', '') IS NULL
     OR NULLIF(identity_signature ->> 'grain_boundary', '') IS NULL
     OR jsonb_typeof(identity_signature -> 'programs') <> 'array'
     OR jsonb_typeof(identity_signature -> 'conditions') <> 'array'
     OR jsonb_typeof(identity_signature -> 'presentations') <> 'array'
     OR jsonb_typeof(identity_signature -> 'recipe_terms') <> 'array'
     OR jsonb_array_length(identity_signature -> 'recipe_terms') = 0
  LIMIT 1;

  IF FOUND THEN
    RAISE EXCEPTION 'Purina Pro Plan protected identity boundary is unsafe: %', v_key;
  END IF;

  SELECT payload.alias_formula_key
  INTO v_key
  FROM purina_pro_plan_retailer_alias_payload payload
  WHERE NOT EXISTS (
    SELECT 1
    FROM public.product_data product
    WHERE product.cache_key = payload.target_cache_key
      AND lower(btrim(product.brand)) = 'purina pro plan'
      AND lower(btrim(product.product_name)) =
          lower(btrim(payload.target_product_name))
      AND lower(btrim(product.product_line)) =
          lower(btrim(payload.target_product_line))
      AND coalesce(lower(btrim(product.flavor)), '') =
          coalesce(lower(btrim(payload.target_flavor)), '')
      AND product.pet_type = payload.target_pet_type
      AND coalesce(
            nullif(lower(btrim(product.life_stage)), 'unknown'),
            ''
          ) = coalesce(
            nullif(lower(btrim(payload.target_life_stage)), 'unknown'),
            ''
          )
      AND product.food_form = payload.target_food_form
      AND product.source_url = payload.target_source_url
      AND product.image_url = payload.target_database_image_url
      AND product.gtin = payload.target_gtin
      AND product.package_size = payload.target_package_size
      AND product.ingredient_count = payload.target_ingredient_count
      AND coalesce(
            nullif(
              product.formula_version_provenance ->> 'ingredient_text_hash',
              ''
            ),
            encode(
              digest(
                public.catalog_normalize_ingredient_evidence(product.ingredient_text),
                'sha256'
              ),
              'hex'
            )
          ) = payload.target_database_ingredient_hash
      AND encode(
            digest(
              btrim(regexp_replace(product.ingredient_text, '\s+', ' ', 'g')),
              'sha256'
            ),
            'hex'
          ) = payload.target_raw_ingredient_hash
      AND product.formula_evidence_tier = 'manufacturer_current_exact'
      AND product.source_quality = 'manufacturer'
      AND product.ingredient_verification_status = 'manufacturer'
      AND product.image_verification_status = 'manufacturer'
      AND product.is_complete_food
      AND product.catalog_exclusion_reason IS NULL
      AND product.expires_at > now()
      AND product.verified_at IS NOT NULL
  )
  LIMIT 1;

  IF FOUND THEN
    RAISE EXCEPTION 'Purina Pro Plan serving precondition changed: %', v_key;
  END IF;
END
$payload_guard$;

CREATE TEMP TABLE purina_pro_plan_retailer_alias_resolved
ON COMMIT DROP
AS
SELECT
  payload.*,
  formula.id AS formula_id,
  formula.formula_key AS canonical_formula_key,
  formula.identity_hash AS canonical_identity_hash,
  observation.id AS observation_id,
  observation.product_name AS retailer_observation_title
FROM purina_pro_plan_retailer_alias_payload payload
JOIN public.catalog_formulas formula
  ON formula.id = payload.formula_id_hint
 AND formula.formula_key = payload.expected_catalog_formula_key
 AND formula.promoted_cache_key = payload.target_cache_key
 AND formula.active
 AND formula.verification_status = 'verified'
 AND formula.formula_evidence_tier = 'manufacturer_current_exact'
 AND formula.is_complete_food
 AND lower(btrim(formula.brand)) = 'purina pro plan'
 AND lower(btrim(formula.product_name)) =
     lower(btrim(payload.target_product_name))
 AND lower(btrim(formula.product_line)) =
     lower(btrim(payload.target_product_line))
 AND coalesce(lower(btrim(formula.flavor)), '') =
     coalesce(lower(btrim(payload.target_flavor)), '')
 AND formula.pet_type = payload.target_pet_type
 AND coalesce(
       nullif(lower(btrim(formula.life_stage)), 'unknown'),
       ''
     ) = coalesce(
       nullif(lower(btrim(payload.target_life_stage)), 'unknown'),
       ''
     )
 AND formula.food_form = payload.target_food_form
 AND formula.source_url = payload.target_source_url
 AND formula.front_image_url = payload.target_database_image_url
 AND formula.source_authority = 'manufacturer'
 AND formula.ingredient_verification_status = 'manufacturer'
 AND formula.image_verification_status = 'manufacturer'
 AND coalesce(
       nullif(formula.formula_version_provenance ->> 'ingredient_text_hash', ''),
       encode(
         digest(
           public.catalog_normalize_ingredient_evidence(formula.ingredient_text),
           'sha256'
         ),
         'hex'
       )
     ) = payload.target_database_ingredient_hash
 AND encode(
       digest(
         btrim(regexp_replace(formula.ingredient_text, '\s+', ' ', 'g')),
         'sha256'
       ),
       'hex'
     ) = payload.target_raw_ingredient_hash
JOIN LATERAL (
  SELECT exact_observation.id, exact_observation.product_name
  FROM public.catalog_observations exact_observation
  WHERE exact_observation.source_slug = payload.retailer_source_slug
    AND exact_observation.source_external_id = payload.retailer_product_id
    AND lower(regexp_replace(exact_observation.source_url, '/+$', '')) =
        lower(regexp_replace(payload.retailer_source_url, '/+$', ''))
    AND (
      lower(btrim(exact_observation.product_name)) =
          lower(btrim(payload.retailer_title))
      OR (
        payload.retailer_product_id = '2183254'
        AND lower(btrim(exact_observation.product_name)) =
            lower(btrim(payload.retailer_title || ', can,'))
      )
    )
    AND lower(btrim(exact_observation.brand)) = 'purina pro plan'
    AND exact_observation.pet_type = payload.target_pet_type
    AND exact_observation.food_form = payload.target_food_form
    AND exact_observation.formula_evidence_tier = 'unverified'
    AND coalesce(exact_observation.front_image_url, '') =
        coalesce(payload.retailer_front_image_url, '')
  ORDER BY
    exact_observation.observed_at DESC,
    exact_observation.created_at DESC,
    exact_observation.id DESC
  LIMIT 1
) observation ON TRUE;

DO $resolution_guard$
DECLARE
  v_key TEXT;
BEGIN
  SELECT payload.alias_formula_key
  INTO v_key
  FROM purina_pro_plan_retailer_alias_payload payload
  LEFT JOIN (
    SELECT alias_formula_key, count(*) AS candidate_count
    FROM purina_pro_plan_retailer_alias_resolved
    GROUP BY alias_formula_key
  ) resolved USING (alias_formula_key)
  WHERE coalesce(resolved.candidate_count, 0) <> 1
  LIMIT 1;

  IF FOUND THEN
    RAISE EXCEPTION
      'Purina Pro Plan formula/observation did not resolve uniquely: %',
      v_key;
  END IF;

  SELECT resolved.alias_formula_key
  INTO v_key
  FROM purina_pro_plan_retailer_alias_resolved resolved
  JOIN public.catalog_formula_aliases existing
    USING (alias_formula_key)
  WHERE existing.formula_id <> resolved.formula_id
  LIMIT 1;

  IF FOUND THEN
    RAISE EXCEPTION 'Purina Pro Plan formula alias collision: %', v_key;
  END IF;

  SELECT resolved.alias_formula_key
  INTO v_key
  FROM purina_pro_plan_retailer_alias_resolved resolved
  JOIN public.catalog_verified_product_search_aliases existing
    ON existing.active
   AND existing.normalized_alias = resolved.normalized_alias
  WHERE existing.cache_key <> resolved.target_cache_key
  LIMIT 1;

  IF FOUND THEN
    RAISE EXCEPTION 'Purina Pro Plan search alias collision: %', v_key;
  END IF;
END
$resolution_guard$;

INSERT INTO public.catalog_formula_aliases (
  alias_formula_key,
  formula_id,
  identity_hash,
  match_reason,
  source_url,
  metadata,
  updated_at
)
SELECT
  resolved.alias_formula_key,
  resolved.formula_id,
  resolved.canonical_identity_hash,
  'manual_review',
  resolved.retailer_source_url,
  jsonb_build_object(
    'source', 'purina_pro_plan_exact_retailer_identity_reconciliation_20260804',
    'review_method', resolved.review_method,
    'review_reason', resolved.review_reason,
    'retailer_identity_only', TRUE,
    'retailer_ingredient_verification', FALSE,
    'manual_package_image_match', resolved.manual_package_image_match,
    'retailer_source_slug', resolved.retailer_source_slug,
    'retailer_product_id', resolved.retailer_product_id,
    'retailer_title', resolved.retailer_title,
    'retailer_observation_title', resolved.retailer_observation_title,
    'retailer_source_url', resolved.retailer_source_url,
    'retailer_front_image_url', resolved.retailer_front_image_url,
    'retailer_front_image_sha256', resolved.retailer_front_image_sha256,
    'retailer_observed_at', resolved.retailer_observed_at,
    'official_source_url', resolved.target_source_url,
    'official_artifact_image_url', resolved.target_artifact_image_url,
    'official_artifact_image_sha256',
      resolved.target_artifact_image_sha256,
    'official_database_image_url', resolved.target_database_image_url,
    'official_cache_key', resolved.target_cache_key,
    'official_gtin', resolved.target_gtin,
    'official_package_size', resolved.target_package_size,
    'canonical_formula_key', resolved.canonical_formula_key,
    'database_ingredient_text_hash',
      resolved.target_database_ingredient_hash,
    'canonical_artifact_ingredient_hash',
      resolved.target_canonical_ingredient_hash,
    'raw_current_ingredient_hash', resolved.target_raw_ingredient_hash,
    'ingredient_count', resolved.target_ingredient_count,
    'identity_signature', resolved.identity_signature,
    'shelf_brand_boundary', resolved.target_brand,
    'species_boundary', resolved.target_pet_type,
    'life_stage_boundary', resolved.target_life_stage,
    'food_form_boundary', resolved.target_food_form,
    'package_size_is_sku_only', TRUE,
    'ingredient_or_image_rewrite', FALSE,
    'reviewed_at', now()
  ),
  now()
FROM purina_pro_plan_retailer_alias_resolved resolved
ON CONFLICT (alias_formula_key) DO UPDATE
SET formula_id = EXCLUDED.formula_id,
    identity_hash = EXCLUDED.identity_hash,
    match_reason = EXCLUDED.match_reason,
    source_url = EXCLUDED.source_url,
    metadata = public.catalog_formula_aliases.metadata || EXCLUDED.metadata,
    updated_at = now()
WHERE public.catalog_formula_aliases.formula_id = EXCLUDED.formula_id;

INSERT INTO public.catalog_verified_product_search_aliases (
  cache_key,
  alias_text,
  normalized_alias,
  source_url,
  source_authority,
  evidence_observed_at,
  provenance,
  active,
  updated_at
)
SELECT
  resolved.target_cache_key,
  resolved.retailer_title,
  resolved.normalized_alias,
  resolved.retailer_source_url,
  'retailer_identity',
  resolved.retailer_observed_at,
  jsonb_build_object(
    'source', 'purina_pro_plan_exact_retailer_identity_reconciliation_20260804',
    'review_method', resolved.review_method,
    'retailer_identity_only', TRUE,
    'retailer_ingredient_verification', FALSE,
    'manual_package_image_match', resolved.manual_package_image_match,
    'retailer_source_slug', resolved.retailer_source_slug,
    'retailer_product_id', resolved.retailer_product_id,
    'retailer_source_url', resolved.retailer_source_url,
    'retailer_observation_title', resolved.retailer_observation_title,
    'retailer_front_image_url', resolved.retailer_front_image_url,
    'retailer_front_image_sha256', resolved.retailer_front_image_sha256,
    'official_source_url', resolved.target_source_url,
    'official_artifact_image_url', resolved.target_artifact_image_url,
    'official_artifact_image_sha256',
      resolved.target_artifact_image_sha256,
    'official_database_image_url', resolved.target_database_image_url,
    'formula_id', resolved.formula_id,
    'canonical_formula_key', resolved.canonical_formula_key,
    'database_ingredient_text_hash',
      resolved.target_database_ingredient_hash,
    'canonical_artifact_ingredient_hash',
      resolved.target_canonical_ingredient_hash,
    'raw_current_ingredient_hash', resolved.target_raw_ingredient_hash,
    'identity_signature', resolved.identity_signature,
    'shelf_brand_boundary', resolved.target_brand,
    'species_boundary', resolved.target_pet_type,
    'life_stage_boundary', resolved.target_life_stage,
    'food_form_boundary', resolved.target_food_form,
    'ingredient_or_image_rewrite', FALSE
  ),
  TRUE,
  now()
FROM purina_pro_plan_retailer_alias_resolved resolved
ON CONFLICT (normalized_alias) WHERE active DO UPDATE
SET cache_key = EXCLUDED.cache_key,
    alias_text = EXCLUDED.alias_text,
    source_url = EXCLUDED.source_url,
    source_authority = EXCLUDED.source_authority,
    evidence_observed_at = EXCLUDED.evidence_observed_at,
    provenance =
      public.catalog_verified_product_search_aliases.provenance
      || EXCLUDED.provenance,
    updated_at = now()
WHERE public.catalog_verified_product_search_aliases.cache_key =
      EXCLUDED.cache_key;

INSERT INTO public.catalog_field_evidence (
  formula_id,
  observation_id,
  field_name,
  field_value,
  source_url,
  source_authority,
  accepted,
  observed_at,
  content_hash
)
SELECT
  resolved.formula_id,
  resolved.observation_id,
  'retailer_exact_identity_alias',
  jsonb_build_object(
    'source', 'purina_pro_plan_exact_retailer_identity_reconciliation_20260804',
    'review_method', resolved.review_method,
    'review_reason', resolved.review_reason,
    'retailer_identity_only', TRUE,
    'retailer_ingredient_verification', FALSE,
    'manual_package_image_match', resolved.manual_package_image_match,
    'retailer_title', resolved.retailer_title,
    'retailer_observation_title', resolved.retailer_observation_title,
    'retailer_product_id', resolved.retailer_product_id,
    'retailer_source_slug', resolved.retailer_source_slug,
    'retailer_front_image_url', resolved.retailer_front_image_url,
    'retailer_front_image_sha256', resolved.retailer_front_image_sha256,
    'official_source_url', resolved.target_source_url,
    'official_artifact_image_url', resolved.target_artifact_image_url,
    'official_artifact_image_sha256',
      resolved.target_artifact_image_sha256,
    'official_database_image_url', resolved.target_database_image_url,
    'official_cache_key', resolved.target_cache_key,
    'official_gtin', resolved.target_gtin,
    'official_package_size', resolved.target_package_size,
    'canonical_formula_key', resolved.canonical_formula_key,
    'database_ingredient_text_hash',
      resolved.target_database_ingredient_hash,
    'canonical_artifact_ingredient_hash',
      resolved.target_canonical_ingredient_hash,
    'raw_current_ingredient_hash', resolved.target_raw_ingredient_hash,
    'identity_signature', resolved.identity_signature,
    'shelf_brand_boundary', resolved.target_brand,
    'species_boundary', resolved.target_pet_type,
    'life_stage_boundary', resolved.target_life_stage,
    'food_form_boundary', resolved.target_food_form,
    'package_size_is_sku_only', TRUE,
    'ingredient_or_image_rewrite', FALSE
  ),
  resolved.retailer_source_url,
  'retailer_identity',
  TRUE,
  resolved.retailer_observed_at,
  encode(
    digest(
      resolved.formula_id::TEXT
      || '|purina_pro_plan_retailer_identity|'
      || resolved.alias_formula_key
      || '|'
      || resolved.retailer_source_url
      || '|'
      || resolved.target_database_ingredient_hash
      || '|'
      || resolved.target_raw_ingredient_hash,
      'sha256'
    ),
    'hex'
  )
FROM purina_pro_plan_retailer_alias_resolved resolved
ON CONFLICT (
  formula_id,
  field_name,
  source_url,
  content_hash
) DO UPDATE
SET observation_id = EXCLUDED.observation_id,
    field_value = EXCLUDED.field_value,
    source_authority = EXCLUDED.source_authority,
    accepted = TRUE,
    observed_at = EXCLUDED.observed_at;

DO $postconditions$
DECLARE
  v_resolved RECORD;
  v_top_cache_key TEXT;
  v_key TEXT;
BEGIN
  IF (
    SELECT count(*)
    FROM purina_pro_plan_retailer_alias_resolved resolved
    JOIN public.catalog_formula_aliases alias
      USING (alias_formula_key)
    WHERE alias.formula_id = resolved.formula_id
      AND alias.match_reason = 'manual_review'
      AND alias.metadata ->> 'source' =
          'purina_pro_plan_exact_retailer_identity_reconciliation_20260804'
      AND alias.metadata ->> 'review_method' =
          'exact_purina_pro_plan_retailer_identity_only'
      AND (alias.metadata ->> 'retailer_identity_only')::BOOLEAN
      AND NOT (alias.metadata ->> 'retailer_ingredient_verification')::BOOLEAN
  ) <> 8 THEN
    RAISE EXCEPTION 'Purina Pro Plan formula alias postcondition failed';
  END IF;

  IF (
    SELECT count(*)
    FROM purina_pro_plan_retailer_alias_resolved resolved
    JOIN public.catalog_verified_product_search_aliases alias
      ON alias.active
     AND alias.normalized_alias = resolved.normalized_alias
    WHERE alias.cache_key = resolved.target_cache_key
      AND alias.source_authority = 'retailer_identity'
      AND alias.provenance ->> 'source' =
          'purina_pro_plan_exact_retailer_identity_reconciliation_20260804'
      AND (alias.provenance ->> 'retailer_identity_only')::BOOLEAN
      AND NOT (alias.provenance ->> 'retailer_ingredient_verification')::BOOLEAN
  ) <> 8 THEN
    RAISE EXCEPTION 'Purina Pro Plan search alias postcondition failed';
  END IF;

  IF (
    SELECT count(*)
    FROM purina_pro_plan_retailer_alias_resolved resolved
    JOIN public.catalog_field_evidence evidence
      ON evidence.formula_id = resolved.formula_id
     AND evidence.observation_id = resolved.observation_id
     AND evidence.field_name = 'retailer_exact_identity_alias'
     AND evidence.source_url = resolved.retailer_source_url
    WHERE evidence.accepted
      AND evidence.source_authority = 'retailer_identity'
      AND evidence.field_value ->> 'source' =
          'purina_pro_plan_exact_retailer_identity_reconciliation_20260804'
      AND (evidence.field_value ->> 'retailer_identity_only')::BOOLEAN
      AND NOT (
        evidence.field_value ->> 'retailer_ingredient_verification'
      )::BOOLEAN
  ) <> 8 THEN
    RAISE EXCEPTION 'Purina Pro Plan field-evidence postcondition failed';
  END IF;

  FOR v_resolved IN
    SELECT *
    FROM purina_pro_plan_retailer_alias_resolved
    ORDER BY alias_formula_key
  LOOP
    SELECT result.cache_key
    INTO v_top_cache_key
    FROM public.search_verified_products(v_resolved.retailer_title, 8) result
    ORDER BY result.rank DESC
    LIMIT 1;

    IF v_top_cache_key IS DISTINCT FROM v_resolved.target_cache_key THEN
      RAISE EXCEPTION
        'Purina Pro Plan exact-title search regression for %: expected %, got %',
        v_resolved.retailer_product_id,
        v_resolved.target_cache_key,
        v_top_cache_key;
    END IF;

    IF EXISTS (
      SELECT 1
      FROM public.search_verified_products(v_resolved.retailer_title, 8) result
      WHERE lower(btrim(result.brand)) <> 'purina pro plan'
         OR result.pet_type <> v_resolved.target_pet_type
         OR result.food_form <> v_resolved.target_food_form
    ) THEN
      RAISE EXCEPTION
        'Purina Pro Plan exact-title search crossed a hard boundary: %',
        v_resolved.retailer_product_id;
    END IF;
  END LOOP;

  SELECT resolved.alias_formula_key
  INTO v_key
  FROM purina_pro_plan_retailer_alias_resolved resolved
  WHERE NOT EXISTS (
    SELECT 1
    FROM public.product_data product
    WHERE product.cache_key = resolved.target_cache_key
      AND product.source_url = resolved.target_source_url
      AND product.image_url = resolved.target_database_image_url
      AND product.gtin = resolved.target_gtin
      AND product.package_size = resolved.target_package_size
      AND product.ingredient_count = resolved.target_ingredient_count
      AND coalesce(
            nullif(
              product.formula_version_provenance ->> 'ingredient_text_hash',
              ''
            ),
            encode(
              digest(
                public.catalog_normalize_ingredient_evidence(product.ingredient_text),
                'sha256'
              ),
              'hex'
            )
          ) = resolved.target_database_ingredient_hash
      AND encode(
            digest(
              btrim(regexp_replace(product.ingredient_text, '\s+', ' ', 'g')),
              'sha256'
            ),
            'hex'
          ) = resolved.target_raw_ingredient_hash
      AND product.formula_evidence_tier = 'manufacturer_current_exact'
      AND product.source_quality = 'manufacturer'
      AND product.ingredient_verification_status = 'manufacturer'
      AND product.image_verification_status = 'manufacturer'
  )
  LIMIT 1;

  IF FOUND THEN
    RAISE EXCEPTION 'Purina Pro Plan identity migration changed serving evidence: %', v_key;
  END IF;

  IF EXISTS (
    SELECT 1
    FROM purina_pro_plan_retailer_alias_resolved resolved
    JOIN public.catalog_formulas formula
      ON formula.promoted_cache_key = resolved.target_cache_key
     AND formula.active
     AND formula.verification_status = 'verified'
    GROUP BY resolved.target_cache_key
    HAVING count(*) <> 1
  ) THEN
    RAISE EXCEPTION 'Purina Pro Plan cache has multiple active verified formulas';
  END IF;
END
$postconditions$;
